import{_ as o,c as r,o as s,a2 as n}from"./chunks/framework.CHomSxuB.js";const i=JSON.parse('{"title":"1. 首板先锋：唯一还活着的线（Step 1 回测 + Step 4 前向）","description":"","frontmatter":{},"headers":[],"relativePath":"A股量化验证/1-首板先锋.md","filePath":"A股量化验证/1-首板先锋.md"}'),g={name:"A股量化验证/1-首板先锋.md"};function d(a,t,e,u,q,l){return s(),r("div",null,t[0]||(t[0]=[n(`<h1 id="_1-首板先锋-唯一还活着的线-step-1-回测-step-4-前向" tabindex="-1">1. 首板先锋：唯一还活着的线（Step 1 回测 + Step 4 前向） <a class="header-anchor" href="#_1-首板先锋-唯一还活着的线-step-1-回测-step-4-前向" aria-label="Permalink to &quot;1. 首板先锋：唯一还活着的线（Step 1 回测 + Step 4 前向）&quot;">​</a></h1><blockquote><p>全系统唯一在回测层跑出显著正期望、且正在<strong>前向验证</strong>的底座。 状态：🔴 前向追踪中（截至 2026-10-16，38 个交易日 / 17 个可成交样本；<strong>2026-09-14 已到达终审点、判定 PASS</strong>， <strong>09-28 再触发&quot;n≥15 提前终审&quot;路径</strong>；V0.4.7 无自动停机故继续推进；净 Ev 在终审点后回落后小幅回摆至 +1.66%， 但<strong>最近 7 个信号日 6 天不可成交、样本连续 4 日停滞在 17</strong>）</p></blockquote><h2 id="假设" tabindex="-1">假设 <a class="header-anchor" href="#假设" aria-label="Permalink to &quot;假设&quot;">​</a></h2><p><strong>&quot;全市场第一个封死涨停的主板票，次日有超额收益&quot;</strong>——赚的是秒级速度差： 信息同步到所有人之前，最早封板的那只票代表当日最强合力方向。</p><h2 id="信号定义-冻结-不可改" tabindex="-1">信号定义（冻结，不可改） <a class="header-anchor" href="#信号定义-冻结-不可改" aria-label="Permalink to &quot;信号定义（冻结，不可改）&quot;">​</a></h2><ul><li>宇宙：纯主板（60xxxx / 00xxxx），剔除 ST/*ST、剔除新股</li><li>每日信号：涨停池中 <code>first_limit_up_time</code>（秒级 epoch）最早者</li><li>平局：<code>order_amount</code>（封单额）降序 → <code>code</code> 升序</li><li>执行：T 日盘中以涨停价排板买入 → T+1 收盘卖出（双边 0.35% 摩擦）</li></ul><h2 id="step-1-回测结果-v0-4-2-口径-243-交易日" tabindex="-1">Step 1 回测结果（v0.4.2 口径，243 交易日） <a class="header-anchor" href="#step-1-回测结果-v0-4-2-口径-243-交易日" aria-label="Permalink to &quot;Step 1 回测结果（v0.4.2 口径，243 交易日）&quot;">​</a></h2><p>判定子集：<strong>纯主板可成交样本 n=95</strong>，bootstrap 10,000 次按日重采样，BH-FDR Q=0.05。</p><table tabindex="0"><thead><tr><th>指标</th><th>n</th><th>mean</th><th>双尾 p</th><th>BH 显著</th></tr></thead><tbody><tr><td>Ev(Close) 收盘收益</td><td>95</td><td><strong>+0.0288</strong></td><td>0.0000</td><td>✅</td></tr><tr><td>超额 vs 中证1000</td><td>95</td><td><strong>+0.0302</strong></td><td>0.0002</td><td>✅</td></tr></tbody></table><p><strong>判定：有 edge（进入 Step 4）</strong> —— 注意这是<strong>回测层</strong>判决，真实可交易性要靠前向验证回答。</p><h2 id="关键事实-可成交率只有-43-6" tabindex="-1">关键事实：可成交率只有 43.6% <a class="header-anchor" href="#关键事实-可成交率只有-43-6" aria-label="Permalink to &quot;关键事实：可成交率只有 43.6%&quot;">​</a></h2><p>241 个有信号的交易日里，仅 105 天次日能正常买进（<code>n_fill=105</code>，executable_rate=43.6%）； 剩余 56.4% 因 T+1 一字/近一字开盘（≥基准×1.095）被判定 <strong>UNFILLED —— 散户通道根本排不进</strong>。</p><table tabindex="0"><thead><tr><th>全样本（Paper，含不可成交）</th><th>n=241</th><th>Ev(Close) <strong>+0.0697</strong></th></tr></thead><tbody><tr><td>纯主板可成交（tradable，判定基准）</td><td>n=95</td><td>Ev(Close) <strong>+0.0288</strong></td></tr></tbody></table><p>最赚钱的那批超级先锋（秒板/一字）恰恰是散户买不到的；能买到的 43.6% 是 <strong>分歧偏大、封单偏弱的次强标的</strong>。即便如此，剔除&quot;买不到幻觉&quot;后可成交样本 依然显著为正——<strong>alpha 不是靠纸上富贵堆出来的</strong>。这是 Step 4 敢继续跑下去的理由。</p><h2 id="step-4-前向追踪-真金白银的账本-但不花真钱" tabindex="-1">Step 4 前向追踪（真金白银的账本，但不花真钱） <a class="header-anchor" href="#step-4-前向追踪-真金白银的账本-但不花真钱" aria-label="Permalink to &quot;Step 4 前向追踪（真金白银的账本，但不花真钱）&quot;">​</a></h2><p>回测会骗人（过拟合/幸存者偏差/&quot;早知道&quot;）。Step 4 换个玩法：从 2026-08-19 起， 每天收盘后按冻结规则记录当日信号，<strong>次日 15:15 自动结算真实结果</strong>，只记账不花钱， 攒够样本后按<strong>事先冻结的生死线</strong>判决。</p><p>状态机（冻结判准，最新版 V0.4.7）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>终审时机：Day≥20 且可成交 n≥8，或 n≥15（提前终审），或 Day≥40（硬上限强制评估）</span></span>
<span class="line"><span>PASS = 可成交 n≥8 ∧ 净 Ev&gt;0 ∧ 累计超额(vs 000852) &gt; -2%</span></span>
<span class="line"><span>停止条件 = 用户手动叫停，或终审点自然到达（V0.4.7 起不再有自动熔断停机）</span></span>
<span class="line"><span>风险事件 = 独立记录（回撤跨 8% 台阶 / 连续大亏），供终审白皮书披露，不进 PASS 布尔逻辑</span></span></code></pre></div><blockquote><p><strong>判据修订留痕</strong>：V0.4.4 口径澄清（纯文案，零公式改动）→ V0.4.5 结算槽位 15:15→15:35、涨停池每次抓取即落盘 → V0.4.6 熔断由&quot;单次触发即停机&quot;改为&quot;累计 5 次&quot; → <strong>V0.4.7 熔断停机整体移除</strong>。 四次修订<strong>均未触及</strong>宇宙 / 收益定义 / 摩擦 0.35% / unfilled 闸 / 终审时机；每次修订都留卷宗。 V0.4.7 的正当性：研究线无资金损失，任意停机阈值都是人为参数（选 1 还是选 5 都是拍脑袋）， 移除比选魔法数字更干净；风险信息改由事件记录承载——<strong>记录风险 ≠ 忽视风险</strong>。 客观效果是观察窗口不再被任何规则打断，故终审白皮书须完整披露&quot;同日两次放宽停机&quot;的判据变更史。</p></blockquote><h3 id="一次真实的判准分歧-2026-09-04-值得留档" tabindex="-1">一次真实的判准分歧（2026-09-04，值得留档） <a class="header-anchor" href="#一次真实的判准分歧-2026-09-04-值得留档" aria-label="Permalink to &quot;一次真实的判准分歧（2026-09-04，值得留档）&quot;">​</a></h3><p>同一份 09-04 数据，三种判准读出三种结论：<strong>旧熔断判准 = KILLED / &quot;20 日或 8 样本&quot;（或）= PASS / 冻结协议&quot;20 日且 8 样本&quot;（且）= 顺延中</strong>。 最终维持协议原文的 <strong>「且」</strong>（继续跑到窗口满 20 日）——理由是：当日刚放宽熔断，若紧接着又放宽终审时机， 两次改动方向一致（都朝&quot;更容易出好结果&quot;），构成判准 shopping（p-hacking），与项目统计纪律冲突。 <strong>这正是&quot;预注册&quot;存在的意义：判准必须在看到结果之前就写死，事后按结果挑判准 = 自欺。</strong></p><h3 id="当前进度-as-of-2026-10-16" tabindex="-1">当前进度（as_of 2026-10-16） <a class="header-anchor" href="#当前进度-as-of-2026-10-16" aria-label="Permalink to &quot;当前进度（as_of 2026-10-16）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>指标</th><th>数值</th><th>生死线</th><th>状态</th></tr></thead><tbody><tr><td>窗口</td><td><strong>38 交易日</strong></td><td>20（可顺延至 40）</td><td>✅ 已过评估点（<strong>距 40 日硬上限仅 2 日</strong>）</td></tr><tr><td>已结算可成交样本</td><td><strong>17</strong></td><td>≥8</td><td>✅ 达标（但已连续 4 个交易日无新增）</td></tr><tr><td>净 Ev（扣 0.35% 摩擦）</td><td><strong>+1.66%</strong></td><td>&gt;0</td><td>✅ 达标（较终审点的 +2.84% 回落 1.18pp）</td></tr><tr><td>胜率</td><td>64.7%（11/17）</td><td>—</td><td>—</td></tr><tr><td>累计超额 vs 中证1000</td><td><strong>+2.00%</strong></td><td>&gt;−2%</td><td>✅ 达标（13 个有效样本）</td></tr><tr><td>最大回撤</td><td><strong>15.93%</strong></td><td>记录项（V0.4.7 起不再熔断）</td><td>已记录（09-28 泰慕士单笔击穿，距 16% 台阶仅 0.07pp）</td></tr><tr><td>风险事件</td><td>1（09-03 集泰股份，回撤首次跨 8% 台阶）</td><td>记录项</td><td>已记录</td></tr><tr><td><strong>判定</strong></td><td>—</td><td>—</td><td><strong>PASS（2026-09-14 达终审点；09-28 再触&quot;n≥15 提前终审&quot;路径，维持 PASS）</strong></td></tr></tbody></table><p>17 笔明细（信号日 / 标的 / 净收益）： 学大教育 +9.64%、日丰股份 −5.21%、汉森制药 +9.66%、协鑫能科 +1.64%、湖南黄金 +6.68%、 我爱我家 +9.65%、海鸥住工 +1.07%、欢瑞世纪 −2.66%、<strong>集泰股份 −10.34%</strong>、<strong>恒盛能源 +8.28%</strong>、 <strong>山子高科 +5.61%</strong>、<strong>中新赛克 −10.33%</strong>、<strong>华瓷股份 +9.67%</strong>、<strong>禾盛新材 −4.46%</strong>、 <strong>泰慕士 −10.35%</strong>、<strong>博纳影业 +3.90%</strong>、<strong>九阳股份 +5.84%</strong>。</p><p>样本推进脉络（09-03 之后）：#8 欢瑞世纪（−2.66%）→ #9 集泰股份（09-03 信号、09-04 结算，<strong>−10.34%</strong>， 当日回撤首次击穿 8% 台阶，即唯一那条风险事件）→ #10 恒盛能源（09-04 信号、09-07 结算，<strong>+8.28%</strong>， 一笔大赚把净 Ev 从 +2.24% 拉回 +2.84%、胜率从 66.7% 回到 70.0%）。 此后 09-08~09-11 的连续信号全部 <strong>UNFILLED</strong>——一字连板在信号位持续&quot;买不进&quot;，n 停在 10，窗口照常推进（19/20）。 终审点之后继续推进：→ #11 山子高科（09-14 信号、09-15 结算，<strong>+5.61%</strong>）→ #12 中新赛克（09-15 信号、09-16 结算， <strong>−10.33%</strong>，一字板次日跌停开盘封死）→ #13 华瓷股份（09-16 信号、09-17 结算，<strong>+9.67%</strong>）。 09-17 信号（中晶科技，T 字板）与 09-18 信号（百通能源，一字首板）继续&quot;买不进&quot; → <strong>UNFILLED</strong>，n 停在 13。 终审点之后第二段推进（09-21~09-24）：09-21 信号（华瓷股份，一字 5 连板）与 09-23 信号（新华传媒，一字 3 连板） 继续 <strong>UNFILLED</strong>；09-22 信号 <strong>禾盛新材</strong>次日一字打开、<strong>可成交</strong> → 结算 <strong>−4.46%</strong>， 成为 <strong>14 个交易日以来的首个负样本（#14）</strong>，净 Ev 由 +2.57% 回落至 <strong>+2.07%</strong>、胜率由 69.2% 降至 <strong>64.3%</strong>。 <strong>样本序列呈现明显的&quot;一字买不进 ↔ 可成交大波动&quot;二分</strong>：能买到的样本里既有 +9.67% 也有 −10.33%、−4.46%。 第三段推进（09-28~09-30）：09-24 信号 <strong>泰慕士</strong>（一字 4 连板）次日<strong>一字跌停开盘封死</strong>、<strong>可成交但极端亏损</strong> → 结算 <strong>−10.35%（#15）</strong>，成为本线<strong>第 2 笔 ≥10% 的单笔亏损</strong>，并把<strong>最大回撤由 12.72% 一次性推到 15.93%</strong> （距 16% 台阶仅 0.07pp）；也正是这一笔让可成交样本达 15，触发 <strong>09-28 的&quot;n≥15 提前终审&quot;</strong>。 随后 09-28 信号 <strong>博纳影业</strong>次日高开 +6.92%（未达一字闸）、可成交 → 结算 <strong>+3.90%（#16）</strong>， 把净 Ev 从 +1.24% 小幅拉回 <strong>+1.40%</strong>、胜率回到 <strong>62.5%</strong>。 09-29 信号（新华传媒，一字 6 连板）继续 <strong>UNFILLED</strong>；09-30 信号（新华传媒，一字 7 连板）待结算。 <strong>&quot;一字买不进&quot;的比例仍在上升</strong>：31 个信号日里 14 天不可成交（45.2%），且越是超级强势的标的越买不进。</p><p>第四段推进（10-08~10-16）：<strong>7 个信号日只有 1 天能成交</strong>。 10-08 / 10-09 / 10-12 连续三笔 <strong>UNFILLED</strong>（均为同一只标的的一字连板延续，8 板 → 9 板 → 10 板）； 10-13 信号 <strong>九阳股份</strong>次日低开 −4.93%、盘中一度 −8.89%、尾盘拉回收 +6.19% → 结算 <strong>+5.84%（#17）</strong>， 这是本段唯一新增样本，也是本线<strong>第 3 次&quot;深 V 反转&quot;式的大额正收益</strong>（前两次：华瓷股份、博纳影业）。 此后 10-14（一字 2 连板）/ 10-15（一字首板）/ 10-16（复牌一字 11 连板）连续三笔 <strong>UNFILLED</strong>， <strong>n 从 10-13 起停在 17，连续 4 个交易日未动</strong>。</p><h3 id="终审点已到-2026-09-14-判定-pass" tabindex="-1">终审点已到：2026-09-14 判定 PASS <a class="header-anchor" href="#终审点已到-2026-09-14-判定-pass" aria-label="Permalink to &quot;终审点已到：2026-09-14 判定 PASS&quot;">​</a></h3><p>窗口推进到第 20 个交易日时（2026-09-14），三条冻结条件同时满足：</p><table tabindex="0"><thead><tr><th>冻结条件</th><th>阈值</th><th>实测（09-14）</th></tr></thead><tbody><tr><td>可成交样本</td><td>n ≥ 8</td><td>10</td></tr><tr><td>净 Ev（扣 0.35% 摩擦）</td><td>&gt; 0</td><td><strong>+2.84%</strong></td></tr><tr><td>累计超额 vs 中证1000</td><td>&gt; −2%</td><td><strong>+3.59%</strong></td></tr></tbody></table><p>→ <strong>状态机首次输出 PASS（通过）</strong>，这是本线前向追踪给出的第一条正式结论。</p><p><strong>PASS ≠ 收工，也 ≠ 可交易</strong>：V0.4.7 移除的是&quot;风险触发式熔断停机&quot;，终审点到达后系统按既定口径继续前向推进 （这正是本表从 10 样本更新到 13 样本、窗口从 20 推到 24 的原因）。继续跑的价值：终审点只是&quot;用冻结判准给一个时点结论&quot;， 样本继续增长才能看出这个结论是真结构还是运气——<strong>目前来看更像&quot;真结构但很薄&quot;</strong>（见下方警示）。</p><blockquote><p>⚠️ <strong>PASS 只是&quot;通过了一条很宽的生死线&quot;，不是&quot;这条路能赚钱&quot;</strong>：净 Ev 仅 +1.40%、样本 16 笔， 期间出现过 <strong>−10.34% / −10.33% / −10.35%</strong> 三笔极端亏损与 <strong>15.93%</strong> 的最大回撤。 生死线（净 Ev&gt;0 ∧ 累计超额&gt;−2%）是为<strong>证伪</strong>设计的宽线，通过只说明&quot;还没被证伪&quot;。 另外要提防&quot;<strong>不熔断 ≠ 能终审</strong>&quot;的误读：V0.4.7 移除停机只影响&quot;能否继续观察&quot;，不影响&quot;当前结论&quot;。 Step 4 的意义恰在于——不在第 5 笔宣布胜利，也不在第 3 笔亏损时恐慌，一切等凑够样本。</p></blockquote><h3 id="pass-之后的压力测试-终审点后数字先退潮、再小幅回摆-2026-09-15-09-30" tabindex="-1">PASS 之后的压力测试：终审点后数字先退潮、再小幅回摆（2026-09-15 ~ 09-30） <a class="header-anchor" href="#pass-之后的压力测试-终审点后数字先退潮、再小幅回摆-2026-09-15-09-30" aria-label="Permalink to &quot;PASS 之后的压力测试：终审点后数字先退潮、再小幅回摆（2026-09-15 ~ 09-30）&quot;">​</a></h3><p>终审点（09-14）之后又推进了 7 个信号日、新增 3 个可成交样本，读数变化如下：</p><table tabindex="0"><thead><tr><th>指标</th><th>09-14 终审点</th><th>09-24</th><th>09-30</th><th>10-16</th><th>终审点→10-16</th></tr></thead><tbody><tr><td>可成交样本</td><td>10</td><td>14</td><td>16</td><td><strong>17</strong></td><td>+7（另有 10 笔 UNFILLED）</td></tr><tr><td>净 Ev（扣摩擦）</td><td>+2.84%</td><td>+2.07%</td><td>+1.40%</td><td><strong>+1.66%</strong></td><td>−1.18pp</td></tr><tr><td>胜率</td><td>70.0%（7/10）</td><td>64.3%（9/14）</td><td>62.5%（10/16）</td><td><strong>64.7%（11/17）</strong></td><td>−5.3pp</td></tr><tr><td>累计超额 vs 中证1000</td><td>+3.59%</td><td>+2.26%</td><td>+1.74%</td><td><strong>+2.00%</strong></td><td>−1.59pp</td></tr></tbody></table><p>终审点之后新增的 4 笔可成交样本里：<strong>禾盛新材 −4.46%</strong> 与 <strong>泰慕士 −10.35%</strong> 两笔亏损、 <strong>博纳影业 +3.90%</strong>、<strong>九阳股份 +5.84%</strong> 两笔小赚——<strong>三项指标整体向下，但中途出现两次小幅回摆</strong> （09-28→09-30 净 Ev +1.24% → +1.40%；10-13 九阳一笔把净 Ev 从 +1.40% 拉回 <strong>+1.66%</strong>、胜率回到 64.7%）， 说明&quot;退潮&quot;也不是单调直线，而是<strong>围绕更低真实值的波动</strong>。</p><p><strong>这与足球线观察到的&quot;到线后退潮&quot;是同一类现象</strong>：判据线到达那一刻的数字，往往是样本尚小时的高点； 样本继续增长，指标向真实值（更低的真实值）回归。<strong>&quot;到线&quot;是取得结论资格，不是结论本身。</strong> 处置上不做任何动作：判据没变、协议没变，继续跑就是最诚实的做法。</p><h2 id="样本停滞-当-信号越准-变成-越买不进-2026-10-08-10-16" tabindex="-1">样本停滞：当&quot;信号越准&quot;变成&quot;越买不进&quot;（2026-10-08 ~ 10-16） <a class="header-anchor" href="#样本停滞-当-信号越准-变成-越买不进-2026-10-08-10-16" aria-label="Permalink to &quot;样本停滞：当&quot;信号越准&quot;变成&quot;越买不进&quot;（2026-10-08 ~ 10-16）&quot;">​</a></h2><p>这一轮最值得记的不是收益，而是一个<strong>结构性约束</strong>第一次压到了前向追踪的节奏上。</p><table tabindex="0"><thead><tr><th>口径</th><th>数值</th><th>说明</th></tr></thead><tbody><tr><td>已判定信号日</td><td>37（38 窗口 − 1 在途）</td><td>08-19 起累计</td></tr><tr><td>其中不可成交（UNFILLED）</td><td><strong>20</strong></td><td>占已判定 <strong>54.1%</strong></td></tr><tr><td>可成交</td><td>17</td><td>占已判定 45.9%</td></tr><tr><td>最近 7 个信号日</td><td><strong>6 天不可成交</strong></td><td>10-08 / 09 / 12 / 14 / 15 / 16</td></tr><tr><td>样本停滞时长</td><td><strong>连续 4 个交易日 n 未动</strong></td><td>10-13 起停在 17</td></tr></tbody></table><p><strong>第一层读法：这不是抽样偶然，是与回测层同构的结构。</strong> 回测层 243 个交易日的可成交率是 <strong>43.6%</strong>， 前向追踪 38 个交易日的可成交率是 <strong>45.9%</strong>——两个独立样本、两套时点，落在同一个量级。 说明&quot;最早封板的那只票，多半排不进单&quot;不是运气问题，而是<strong>信号定义自带的可成交性折扣</strong>： 选择器挑的是&quot;当日最强合力&quot;，而最强的那一档恰恰是散户通道最挤不进去的一档。</p><p><strong>第二层读法：信号越准，样本越慢。</strong> 10-08 至 10-12 连续三个信号日选中的是<strong>同一只标的</strong>（一字连板从 8 板走到 10 板）， 每天都 UNFILLED。这在统计上意味着：<strong>行情越好，本线越没有样本</strong>——样本获取速度与市场强度负相关。 这与&quot;用时间换样本&quot;的设计假设有张力：时间在流逝，样本不一定在增长。</p><p><strong>第三层读法（最重要）：窗口硬上限快到了。</strong> 当前窗口 38，<strong>距 40 日硬上限仅剩 2 个交易日</strong>。 按冻结协议，到 40 日必须强制评估——也就是说，<strong>这条线很可能要用 17 个样本（而非设计预期的更多）出终审结论</strong>。 这不是规则出错，而是规则在&quot;样本不可得&quot;时的正常表现：<strong>协议只能规定&quot;什么时候必须给结论&quot;，不能规定&quot;市场必须给够样本&quot;。</strong></p><blockquote><p><strong>跨项目对照（值得并列看）</strong>：同期足球线的 OOS 样本从 1632 场涨到 2079 场（同一时段 +447 场）， 因为那里的每一场比赛都会自然结算，样本增长只受赛程约束；而这条线的样本增长受<strong>可成交性</strong>约束。 <strong>同一个&quot;样本量&quot;指标，在两个项目里含义完全不同</strong>：一个是&quot;时间过去了多少&quot;，一个是&quot;市场让不让你进场&quot;。 这也解释了为什么本线的置信区间天然比足球线宽——<strong>不是统计方法弱，是有效样本的获取机制不同</strong>。 结论层面的纪律因此更严：<strong>样本停滞时，唯一正确的动作是如实标注&quot;n=17 且增长停滞&quot;，而不是延长窗口去凑样本。</strong></p></blockquote><h2 id="已在运行中暴露并修复的工程问题" tabindex="-1">已在运行中暴露并修复的工程问题 <a class="header-anchor" href="#已在运行中暴露并修复的工程问题" aria-label="Permalink to &quot;已在运行中暴露并修复的工程问题&quot;">​</a></h2><ul><li><strong>注释与实现打架</strong>：docstring 写&quot;T+1 开盘买入&quot;，实现却是&quot;T 收盘成本、T+1 收盘卖出&quot;。 纯文案修复，不动公式 → 见《6. 数据洁净度审计》。</li><li><strong>历史账本口径审计</strong>：对全部 12 笔 SIGNAL 逐笔反推隐含成本价与独立行情重拉比对， 11 笔全 PASS、1 笔待结算 → 历史数据干净，无脏数据回填需求。（09-03：该笔欢瑞世纪已结算为样本 #8。）</li><li><strong>涨停池定稿前落盘（2026-09-03，V0.4.5）</strong>：每日结算槽位 15:15 → 15:35（对齐涨停池 15:30 定稿， 避开结算窗脏数据）；涨停池每次抓取即落盘存档——根治&quot;当日用完即弃&quot;导致的 08-19~09-01 涨停池 历史缺口（此前只能依赖不可回溯的外部数据回填，该问题曾是历史审计的最大软肋）。</li><li><strong>判据变更必须是纯函数（V0.4.6，2026-09-04）</strong>：把停机计数从&quot;每日 +1 的持久化计数器&quot;改为 <strong>由账本直接推导</strong>——理由：持久化计数器会让同一持续状态在 N 天后必然误停机，且历史不可复现、改规则要迁移； 纯函数方案免迁移、幂等、任何人拿账本都能独立复算。同输入重复计算 3 次结果一致（幂等校验通过）。</li><li><strong>报告字段 tie-break 缺陷（2026-09-10 起，共 9 次暴露，未修，待裁决）</strong>：预案报告&quot;最高标&quot;字段按&quot;N 天&quot;取最大值， 而&quot;N 天 4 板&quot;与&quot;N 天 2 板&quot;会在天数上打平 → 反复误标。已暴露的形态：09-10 平局取先遍历者；09-11 &quot;5 天 3 板&quot;压过 真实的&quot;4 天 4 板&quot;；09-17 按&quot;N 天&quot;得唯一最大（8 天 5 板）但按&quot;板数&quot;与另一只 5 天 5 板<strong>并列</strong>；09-18 则 6 天 3 板 压过真实的 4 天 4 板（真实最高连板 = 两只 4 天 4 板并列）；09-21 再现平局型（同为&quot;5 天&quot;的 5 天 5 板 vs 5 天 4 板）； 09-23 双高标同步误判、09-24 并列取天数多者、09-28 两口径一致无歧义；10-09 按天数取&quot;15 天 9 板&quot;压过 同为 9 板的&quot;9 天 9 板&quot;；10-12 报告写&quot;11 天 8 板&quot;，而按板数真实最高是 10 连板那只；10-16 再复现（见下条）。 正确排序键应是<strong>连板数</strong>而非&quot;N 天&quot;，并列时还需第三条判据。 <strong>未擅自改脚本</strong>（排序口径属判据，改动须用户拍板），已在预案内标注真值。</li><li><strong>&quot;最高标&quot;的口径分歧升级为概念级（2026-10-15，未修，待裁决）</strong>：此前九次都是<strong>排序键选错</strong>， 这一轮暴露出更根本的一层——<strong>&quot;累计板数&quot;与&quot;连续连板数&quot;是两个不同的量</strong>。 脚本取的是&quot;累计涨停板数×65536 + 天数&quot;的复合键，于是把&quot;断板后又反包、累计 11 板&quot;的标的排到最前； 而按&quot;<strong>连续</strong>连板&quot;口径，真实最高只有 <strong>5 连板</strong>（两只并列）。 两者对&quot;谁是最高标&quot;的回答可以完全相反，进而影响&quot;最高标是否断板&quot;这一<strong>环境闸门的总开关</strong>。 处置：仅在预案附注中并列标注两种口径，<strong>未改脚本、未改闸门</strong>——因为闸门一旦改口径， 等于回溯性改写历史每一次 B 决策的归因，必须走协议修订（新版本号 + 全量重算），不是执行层能自裁的事。</li><li><strong>停牌股进入高度统计（2026-10-13 ~ 10-16，新增观测）</strong>：一只高位股连续 3 个交易日停牌， 期间既无开盘价也无成交，第四日复牌直接一字涨停并刷新高度。停牌在&quot;最高标&quot;统计里产生了两个副作用： ①它<strong>不参与</strong>当日的&quot;是否续板&quot;判定（无行情），容易被误读为&quot;已断板&quot;； ②复牌一字又把它送回高度榜首，使&quot;最高标&quot;序列出现 3 天空窗后跳变。 处置：把&quot;停牌&quot;单列为一种<strong>非常规状态</strong>（既非续板也非断板），在预案与账本备注中显式标注； <strong>未改脚本</strong>（是否把停牌从高度统计中剔除，属判据问题）。</li><li><strong>结算数据缺口：<code>excess</code> 落空后永不再补算（2026-09-14，未修，待裁决）</strong>：结算函数只处理仍处 SIGNAL 状态的行， 若结算当日基准指数收盘价取不到，该行 <code>excess</code> 落空且此后<strong>永不再补算</strong>（09-14 山子高科即此例）。 后果：截至 10-16 累计超额实际用 <strong>13 个有效样本</strong>而非 17 个（该行始终未补算），比正确值<strong>偏低</strong>—— <strong>对 PASS 判定无影响</strong>（三条件仍满足），但属口径偏差，修复需改脚本或手工回填，属判据外变更 → 留用户拍板。</li><li><strong>报告显示层两处口径不一致（2026-09-15 起暴露，未修）</strong>：①报告第五节&quot;窗口：N 交易日&quot;渲染的是<strong>预注册阈值常量</strong>， 而非状态机里的<strong>实际窗口</strong>——09-14 之前两者相等故未暴露，09-15 起分离（09-21 实际 25、09-24 实际 28、09-29 实际 30、 <strong>10-16 实际 38，均显示 20</strong>）；②&quot;连板分布&quot;行按固定 6 类截断显示，导致合计不等于当日涨停总数 （09-14/09-16/09-17/09-18/09-21/09-22/09-29/10-09/10-14/10-15/10-16 均复现；10-14 漏&quot;3 天 3 板&quot;与&quot;7 天 4 板&quot;两类，10-16 漏两类共 2 只）。 <strong>两者均为显示层问题、不影响统计与判定</strong>，未改脚本。</li><li><strong>涨停池一处字段缺失（2026-09-28，未修）</strong>：某只当日涨停股的&quot;连板高度&quot;两个字段双双缺失，导致它既未计入 连板分布、也没进任何高度分类（当日连板分布合计比涨停总数少 1）。属<strong>上游数据缺字段</strong>，非本项目口径问题； 报告按原样渲染，<strong>未擅自补值</strong>——补值等于自造数据，比缺一个字段更危险。</li><li><strong>行情接口的&quot;日线节点滞后&quot;坑（2026-09-24）</strong>：日线类接口对<strong>个股当日 K 线</strong>存在延迟（收盘后一段时间仍未落库）， 但<strong>指数正常</strong>；若用日线节点取个股当日收盘价会取到空值或旧值。正确做法是当日收盘价改用<strong>实时快照节点</strong>。 指数与个股的取数路径不能混用——这是&quot;交易日校验金标准&quot;（见《7. 模拟盘执行线》）的同源教训。</li><li><strong>全时间线回放能力转正（2026-09-05）</strong>：可对任意历史日&quot;用历史数据重新执行&quot;整条时间线 （盘后结算 → 次日 09:31 决策 → 14:57 结算），并以独立工作区账本与生产账本零接触。 铁律：报告必须由数据现算（禁止拿历史报告渲染充数）、旧口径不得混入、数据缺口整段顺延不补录。</li></ul><h2 id="已知物理局限-写进终审白皮书的清单项" tabindex="-1">已知物理局限（写进终审白皮书的清单项） <a class="header-anchor" href="#已知物理局限-写进终审白皮书的清单项" aria-label="Permalink to &quot;已知物理局限（写进终审白皮书的清单项）&quot;">​</a></h2><ul><li>T+1 一字跌停时仍按收盘价记账（实际可能卖不出/卖得更低）→ 轻微多头乐观偏差； 协议冻结期不修，待终审白皮书列入 Known Limitations。</li><li><strong>风控真空（V0.4.7 起）</strong>：本线不再有任何自动刹车。研究线无资金损失，故可接受； 但若此口径被复制到实盘，<strong>绝对不可照搬</strong>——实盘必须有独立于研究线的风控层。</li><li><strong>人工叫停无预注册标准</strong>：停止条件含&quot;用户手动叫停&quot;，其触发条件未定义（设计使然，留给人的判断）， 意味着停机决策不可复现；白皮书如涉及中途叫停，须记录当时的完整决策上下文。</li></ul><hr><p><strong>互链</strong>：<a href="/A股量化验证/">返回 A股量化验证 首页</a> · 下一篇：<a href="/A股量化验证/2-公告排雷.html">2. 公告排雷</a></p>`,50)]))}const p=o(g,[["render",d]]);export{i as __pageData,p as default};
